Output6Using Bottom-Up DP (Tabulation) - O(n) Time and O(n) SpaceThe idea is to fill the DP table based on previous values. For each n, its value is dependent on n-1, n-3 and n-4. The table is filled in an iterative manner from i = 1 to i = n.The dynamic programming relation is as follows: dp[i] = sum(dp[i-j]) for value of j = {1, 3, 4} and i-j >=0.
            C++

    // C++ Program to count the number of ways
// to express N as the sum of 1, 3, and 4
// using tabulation
#include <bits/stdc++.h>
using namespace std;

int countWays(int n) {
    vector<int> dp(n + 1, 0);
    dp[0] = 1;

    for (int i = 1; i <= n; i++) {

        // Calculate dp[i].
        if (i - 1 >= 0)
            dp[i] += dp[i - 1];
        if (i - 3 >= 0)
            dp[i] += dp[i - 3];
        if (i - 4 >= 0)
            dp[i] += dp[i - 4];
    }

    return dp[n];
}

int main() {

    int n = 5;
    cout << countWays(n);
    return 0;
}


