            C++

    // C++ Program to count the number of ways
// to express N as the sum of 1, 3, and 4
// using space optimised dp
#include <bits/stdc++.h>
using namespace std;

int countWays(int n) {

    // Return values for 1st 
    // 4 states
    if (n==1) return 1;
    if (n==2) return 1;
    if (n==3) return 2;
    if (n==4) return 4;

    vector<int> dp(4);
    dp[0] = 1;
    dp[1] = 1;
    dp[2] = 2;
    dp[3] = 4;

    for (int i=5; i<=n; i++) {

        int curr = dp[0]+dp[1]+dp[3];

        // Update values
        dp[0] = dp[1];
        dp[1] = dp[2];
        dp[2] = dp[3];
        dp[3] = curr;
    }

    return dp[3];
}

int main() {
    int n = 5;
    cout << countWays(n);
    return 0;
}


